'use client';

import { useRouter } from "next/navigation"; // ✅ use next/navigation for app router
import { usePathname } from "next/navigation";
import { useEffect } from "react";

interface CardProps {
  experience: ExperienceType;
}

export default function Card({ experience }: CardProps) {
  const router = useRouter();
  const pathname = usePathname();

  const date = new Date(experience.dates[0]);
  const dates = experience.dates.map(date =>
    (new Date(date)).toLocaleDateString("en-US", {
      month: "short",
      day: "numeric",
      year: "numeric"
    })
  );

  function handleClick() {
    router.replace(`./${pathname}/info/${experience._id}`);
  }

  return (
    <div
      onClick={handleClick}
      className="rounded-2xl lg:rounded-4xl bg-[var(--background)] text-[var(--foreground)] w-[70vw] lg:w-[30vw] xl:w-[20vw] aspect-[5/2] lg:aspect-square bubble flex flex-row lg:flex-col items-center justify-between"
    >
      <img
        src={experience.images[0].url}
        alt={experience.images[0].caption}
        className="object-cover h-full w-auto lg:h-auto lg:w-full overflow-clip aspect-square lg:aspect-[3/2] rounded-l-2xl lg:rounded-t-4xl lg:rounded-bl-none"
      />
      <div className="flex-1 w-full text-left font-sans p-2 px-5">
        <h1 className="font-bold text-sm md:text-2xl xl:text-4xl line-clammp-1 line-clamp-2">
          {experience.title}
        </h1>
        <p className="line-clamp-1 text-sm md:text-md xl:text-xl">
          {dates.join(" - ")}
        </p>
        <p className="line-clamp-2 text-sm md:text-md xl:text-xl">
          {experience.description}
        </p>
      </div>
    </div>
  );
}
